   "helper": {
    "id": "gr-g-two-homes-helper",
    "guide": "two-homes",
    "side": "helper",
    "title": "Two Homes After a Separation",
    "sideName": "For the Leader",
    "mins": 3,
    "blurb": "For the parent or grown-up leading children through two homes: lower the conflict, steady the routines, and find support for you.",
    "sources": [
     "amato01"
    ],
    "scenes": [
     {
      "k": "title",
      "hero": "grove",
      "eyebrow": "When Life Changes Together",
      "h": "Two Homes After a Separation",
      "sub": "For the Leader",
      "say": "This is for a parent, stepparent, or grown-up helping children through a separation and life in two homes."
     },
     {
      "k": "big",
      "h": "Conflict matters more than the split.",
      "sub": "And conflict is something you can lower.",
      "say": "Research over many years finds that most children do well over time after their parents separate, and that ongoing conflict between parents is what weighs on them most. That's hopeful news, because conflict is something you can lower."
     },
     {
      "k": "points",
      "h": "Keep them out of the middle",
      "items": [
       [
        "No messages",
        "Talk to each other directly"
       ],
       [
        "No reports",
        "About the other home"
       ],
       [
        "No adult details",
        "Money, court, blame"
       ],
       [
        "Kind words or none",
        "About the other parent"
       ]
      ],
      "say": "Keep children out of the middle. No carrying messages. No reporting on the other home. No adult details about money, court, or blame. And kind words, or none, about the other parent. Talk with each other by text or email, at times the children aren't around."
     },
     {
      "k": "points",
      "h": "Steady the routines",
      "items": [
       [
        "A shared calendar",
        "Kids can see it"
       ],
       [
        "Basics in both homes",
        "Bedtime, homework, screens"
       ],
       [
        "Arriving and leaving",
        "A simple routine"
       ],
       [
        "Holidays planned early",
        "No surprises"
       ]
      ],
      "say": "Steady the routines. Keep a shared calendar the children can see. Match the basics in both homes where you can, like bedtime, homework, and screens. Make a simple routine for arriving and leaving. And plan holidays early, so there are no surprises."
     },
     {
      "k": "big",
      "h": "Write down one thing both homes can share.",
      "sub": "A rule, a routine, or a phrase.",
      "say": "Let's take a moment. Think of one small thing that could be the same in both homes. A bedtime, a goodnight phrase, a rule about phones. Write it down, and choose a calm time to suggest it.",
      "beats": [
       "Let's take a moment.",
       "Think of one small thing that could be the same in both homes.",
       "A bedtime, a goodnight phrase, a rule about phones.",
       {
        "t": "Write it down, and choose a calm time to suggest it.",
        "w": 12
       }
      ]
     },
     {
      "k": "words",
      "h": "Words to set aside",
      "items": [
       "Tell your mother she's late.",
       "You're the man of the house now.",
       "Whose side are you on?"
      ],
      "say": "Some words put children in the middle. Tell your mother she's late again. You're the man of the house now. Whose side are you on? Try instead, you never have to choose. That's a grown-up problem, and we'll handle it."
     },
     {
      "k": "card",
      "title": "Safety first.",
      "body": "Danger: 911. Domestic Violence Hotline: 1-800-799-7233. Childhelp: 1-800-422-4453.",
      "say": "If either home is unsafe, put safety first. In danger, call nine one one. The National Domestic Violence Hotline answers any time for adults, and Childhelp answers for children. If a child stays very sad or withdrawn for weeks, talk with their doctor or school counselor. Thoughts of not wanting to live, call or text nine eight eight."
     },
     {
      "k": "big",
      "h": "Your steadiness matters most.",
      "sub": "The full guide has more, whenever you want it.",
      "say": "You don't need to get every word right. Find people who can hold your feelings, so your children don't have to. Your steadiness matters most. The full guide has more, whenever you want it."
     }
    ]
   }
