      "sub": "The full guide has more, whenever we want it.",
      "say": "Waiting is hard, and it's okay to ask questions while we wait. Grown-ups will tell us what they know, and they will keep looking after us at home. Our love reaches all the way to that hospital room. The full guide has more, whenever we want it."
